function showCatalog() {
  document.getElementById("pageLanding").classList.add("hidden");
  document.getElementById("pageCatalog").classList.remove("hidden");
  window.scrollTo(0, 0);
}
function showLanding() {
  document.getElementById("pageCatalog").classList.add("hidden");
  document.getElementById("pageLanding").classList.remove("hidden");
  window.scrollTo(0, 0);
}

