const CATEGORIES = [
  { id: "all", label: "All Systems" },
  { id: "cbct", label: "CBCT & 3D Imaging" },
  { id: "pano", label: "Panoramic & Cephalometric" },
  { id: "sensor", label: "Intraoral Sensors" },
  { id: "intraoral-xray", label: "Intraoral X-ray Units" },
  { id: "portable", label: "Portable X-ray" },
];

let activeCategory = "all";
let searchTerm = "";

function categoryCount(catId) {
  if (catId === "all") return PRODUCTS.length;
  return PRODUCTS.filter((p) => p.category === catId).length;
}

function renderChips() {
  const wrap = document.getElementById("filterChips");
  wrap.innerHTML = CATEGORIES.map(
    (c) => `
    <button class="chip ${activeCategory === c.id ? "active" : ""}" data-cat="${c.id}">
      ${c.label} <span class="count">${categoryCount(c.id)}</span>
    </button>
  `,
  ).join("");
  wrap.querySelectorAll(".chip").forEach((btn) => {
    btn.addEventListener("click", () => {
      activeCategory = btn.dataset.cat;
      renderChips();
      renderGrid();
    });
  });
}

function matchesSearch(p, term) {
  if (!term) return true;
  const hay = (
    p.name +
    " " +
    p.tagline +
    " " +
    p.categoryLabel +
    " " +
    (p.features || []).join(" ")
  ).toLowerCase();
  return hay.includes(term);
}

function renderGrid() {
  const grid = document.getElementById("productGrid");
  const term = searchTerm.trim().toLowerCase();
  let list = PRODUCTS.filter(
    (p) =>
      (activeCategory === "all" || p.category === activeCategory) &&
      matchesSearch(p, term),
  );

  document.getElementById("resultCount").textContent =
    `${list.length} of ${PRODUCTS.length} systems`;

  if (list.length === 0) {
    grid.innerHTML = `<div class="empty-state"><h3>No matches</h3><p>Try a different term or clear the filter.</p></div>`;
    return;
  }

  grid.innerHTML = list
    .map(
      (p) => `
    <div class="card" data-id="${p.id}" tabindex="0" role="button" aria-label="View ${p.name} details">
      <div class="card-img"><span class="card-tag">${p.categoryLabel}</span><img src="${p.img}" alt="${p.name}" loading="lazy"></div>
      <div class="card-body">
        <div class="card-name">${p.name}${p.badge ? `<span class="badge">${p.badge}</span>` : ""}</div>
        <div class="card-tagline">${p.tagline}</div>
        <div class="card-specs">
          ${p.quickSpecs.map((s) => `<span class="card-spec">${s[0]}: <b>${s[1]}</b></span>`).join("")}
        </div>
        <div class="card-actions">
          <div class="card-more">View full specs <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><path d="M5 12h14M13 6l6 6-6 6"/></svg></div>
          ${pdfBtn(p)}
        </div>
      </div>
    </div>
  `,
    )
    .join("");

  grid.querySelectorAll(".card").forEach((card) => {
    const open = () => openModal(card.dataset.id);
    card.addEventListener("click", open);
    card.addEventListener("keypress", (e) => {
      if (e.key === "Enter") open();
    });
  });
}

const NO_PDF = ["gtis"];
function pdfBtn(p, extraClass) {
  if (NO_PDF.includes(p.id)) return "";
  return `<a class="pdf-btn ${extraClass || ""}" href="#" onclick="event.stopPropagation();event.preventDefault();downloadEmbeddedPDF('${p.id}','${p.name.replace(/[^a-z0-9]+/gi, "_")}.pdf');">
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 3v12m0 0l-4-4m4 4l4-4M4 19h16"/></svg>
    Download PDF
  </a>`;
}

function downloadEmbeddedPDF(id, filename) {
  const url = window.PDF_URLS && window.PDF_URLS[id];
  if (!url) {
    alert("Sorry, this datasheet is not available.");
    return;
  }
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  a.target = "_blank";
  a.rel = "noopener";
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
}

function openModal(id) {
  const p = PRODUCTS.find((x) => x.id === id);
  if (!p) return;
  const modal = document.getElementById("modalContent");
  modal.innerHTML = `
    <button class="modal-close" id="modalCloseBtn" aria-label="Close">&times;</button>
    <div class="modal-hero"><span class="modal-hero-tag">${p.categoryLabel}</span><img src="${p.img}" alt="${p.name}"></div>
    <div class="modal-body">
      <div class="modal-title">${p.name} ${p.badge ? `<span class="badge">${p.badge}</span>` : ""}</div>
      <div class="modal-tagline">${p.tagline}</div>
      ${pdfBtn(p, "modal-pdf-btn")}

      ${
        p.features
          ? `
      <div class="modal-section">
        <h4>Key Features</h4>
        <div class="feature-list">
          ${p.features.map((f) => `<div class="feature-item">${f}</div>`).join("")}
        </div>
      </div>`
          : ""
      }

      ${
        p.variants
          ? `
      <div class="modal-section">
        <h4>Configurations</h4>
        <div class="variant-strip">
          ${p.variants.map((v) => `<div class="variant-pill"><b>${v[0]}</b>${v[1]}</div>`).join("")}
        </div>
      </div>`
          : ""
      }

      <div class="modal-section">
        <h4>Specifications</h4>
        <table class="spec-table">
          ${p.specs.map((s) => `<tr><td>${s[0]}</td><td>${s[1]}</td></tr>`).join("")}
        </table>
        ${p.compareNote ? `<div class="compare-note">${p.compareNote}</div>` : ""}
      </div>
    </div>
  `;
  document
    .getElementById("modalCloseBtn")
    .addEventListener("click", closeModal);
  document.getElementById("modalOverlay").classList.add("open");
  document.body.style.overflow = "hidden";
}

function closeModal() {
  document.getElementById("modalOverlay").classList.remove("open");
  document.body.style.overflow = "";
}

document.getElementById("modalOverlay").addEventListener("click", (e) => {
  if (e.target.id === "modalOverlay") closeModal();
});
document.addEventListener("keydown", (e) => {
  if (e.key === "Escape") closeModal();
});

document.getElementById("searchInput").addEventListener("input", (e) => {
  searchTerm = e.target.value;
  renderGrid();
});

document.getElementById("statTotal").textContent = PRODUCTS.length;
renderChips();
renderGrid();
